head.script:
scwin.simulate = function(element, eventName) {
    var options = scwin.extend(defaultOptions, arguments[2] || {});
    var oEvent, eventType = null;
    for (var name in eventMatchers) {
        if (eventMatchers[name].test(eventName)) {
            eventType = name;
            break;
        }
    }
    if (!eventType)
        throw new TypeError('Only HTMLEvents and MouseEvents interfaces are supported');
    if (document.createEventObject) {
        options.clientX = options.pointerX;
        options.clientY = options.pointerY;
        var evt = document.createEventObject();
        oEvent = scwin.extend(evt, options);
        try {
            element.fireEvent('on' + eventName, oEvent);
        } catch (e) {
            if (element === window) {
                document.fireEvent('on' + eventName);
            }
        }
    } else if (document.createEvent) {
        oEvent = document.createEvent(eventType);
        if (eventType == 'HTMLEvents') {
            oEvent.initEvent(eventName, options.bubbles, options.cancelable);
        } else {
            oEvent.initMouseEvent(eventName, options.bubbles, options.cancelable, document.defaultView,
                options.button, options.pointerX, options.pointerY, options.pointerX, options.pointerY,
                options.ctrlKey, options.altKey, options.shiftKey, options.metaKey, options.button, element);
        }
        element.dispatchEvent(oEvent);
    } else {
        throw new TypeError('Not Supported');
    }
    return element;
}
scwin.tmpSetStatus = function(msg) {
    //windowContainer1.setWindowStatusMsg( msg );
    var tmp = windowContainer1.getWindow("local02");
    tmp.setWindowStatusMsg(msg);
}
scwin.getValue = function(id){
    var iframe = WebSquare.wUnit.getDomById($p.id+"windowContainer1_subWindow0_iframe");
    var elmnt = iframe.contentWindow.WebSquare.wUnit.getDomById($p.id+id);
    return elmnt;
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function(){
    scwin.simulateWrapper(scwin.getValue('popup_header'), 'drag-n-drop', {dx: 0, dy: 60});
}
scwin.setSimulate2 = function(){
    scwin.simulateWrapper(scwin.getValue('popup_header'), 'drag-n-drop', {dx: 0, dy: -60});
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.getValue('textbox2').innerText == 'Merry christmas~~'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "scwin.getValue('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.getValue('popup') != null", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.getValue('popup').style.top == '160px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.getValue('popup').style.top == '100px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();        
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
