		return;
	}else{
		windowContainer1.createWindow( "daum", "", "http://www.daum.net" , "","","selectWindow");	
	}
    sessionStorage.setItem("aa", "11");

    windowContainer1.createWindow( "<input type='button'>", "", "http://www.daum.net" , "","","selectWindow");

    WebSquare.wUnit.getDomById($p.id+"windowContainer1").innerHTML="<div style='top:0px;left:0px;background-color:#ff000000;'>aa</div>";
    alert("123");
    WebSquare.wUnit.getDomById($p.id+"windowContainer1").style.zIndex = "10000";
}
